using Avalonia;using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using StudioClock.Models;using StudioClock.Services;
namespace StudioClock.Views;
public sealed class SettingsWindow:Window
{
 public SettingsWindow(AppSettings s,IStartupService startup){Title="StudioClock – Einstellungen";Width=470;Height=590;CanResize=false;WindowStartupLocation=WindowStartupLocation.CenterOwner;var clock=Picker(s.ClockColor);var bg=Picker(s.BackgroundColor);var led=Picker(s.LedColor);var slider=new Slider{Minimum=10,Maximum=100,Value=s.OpacityPercent,TickFrequency=1,Width=320};var percent=new TextBlock{Text=$"{s.OpacityPercent}%",VerticalAlignment=VerticalAlignment.Center,Width=45};slider.PropertyChanged+=(_,e)=>{if(e.Property==Slider.ValueProperty)percent.Text=$"{(int)Math.Round(slider.Value)}%";};var auto=new CheckBox{Content="Mit dem System starten",IsChecked=s.AutoStart};var ok=new Button{Content="Speichern"};var cancel=new Button{Content="Abbrechen"};ok.Click+=(_,_)=>{s.ClockColor=clock.Color.ToString();s.BackgroundColor=bg.Color.ToString();s.LedColor=led.Color.ToString();s.OpacityPercent=Math.Clamp((int)Math.Round(slider.Value),10,100);var desired=auto.IsChecked==true;try{startup.SetEnabled(desired);s.AutoStart=desired;}catch{s.AutoStart=startup.IsEnabled();}Close(true);};cancel.Click+=(_,_)=>Close(false);Content=new ScrollViewer{Content=new StackPanel{Margin=new Thickness(24),Spacing=12,Children={Label("Uhrfarbe"),clock,Label("Hintergrundfarbe"),bg,Label("LED-Kranzfarbe"),led,Label("Transparenz"),new StackPanel{Orientation=Orientation.Horizontal,Spacing=12,Children={slider,percent}},auto,new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Spacing=8,Children={cancel,ok}}}}};}
 private static ColorPicker Picker(string v)=>new(){Color=Color.Parse(v),IsAlphaEnabled=false,IsAlphaVisible=false};private static TextBlock Label(string t)=>new(){Text=t,FontWeight=FontWeight.SemiBold};
}
